**Problem**: Need to migrate React's deriveSessionStatus utility to an Effect service while following established patterns.

**Solution**: Use the `sync` factory pattern for pure computation services with no lifecycle:

```typescript
export class StatusService extends Effect.Service<StatusService>()("StatusService", {
  sync: () => ({
    computeStatus: (input: ComputeStatusInput): SessionStatus => {
      // Pure computation logic here
    }
