```typescript
// packages/server/src/procedure-decorated.ts
export class DecoratedProcedure<...> extends Procedure<...> {
  actionable(): ProcedureClient<...> {
    'use server'  // Injected at build time

    return createProcedureClient(this, {
      // Server-side execution (no network)
    })
